// This file is generated by AI.

// 配音卡: Monaco 编辑器 (上) + 语句配音操作台 (下)。
//
// 与普通场景编辑卡共享同一份文档与 Monaco model (因此不存在"冻结快照"):
// 解析结果按文档版本缓存, 内容变化时重新解析并重新匹配历史。
// 操作台高度固定, 光标移出对话时只清空内容而不改变布局。

import { Button } from '@fluentui/react-components';
import { ArrowSyncRegular, AddRegular } from '@fluentui/react-icons';
import { useEffect, useRef, useState } from 'react';

import { CodeEditor } from '../components/CodeEditor';
import { useAppStore } from '../state/store';
import { voiceController, DISK_CHECK_MS } from './controller';
import { ExternalChangeDialog } from './ExternalChangeDialog';
import { VoiceHistory } from './VoiceHistory';
import { VoiceSentencePanel } from './VoiceSentencePanel';
import type { SayLine } from '../commands/voice';

export function VoiceCard({ docPath }: { docPath: string }) {
  const doc = useAppStore((state) => state.documents.find((item) => item.path === docPath));
  // 订阅队列与卡片状态变化
  useAppStore((state) => state.voiceTick);
  const card = voiceController.getCard(docPath);
  const activePath = useAppStore((state) => state.activePath);
  const characters = useAppStore((state) => state.voiceCharacters);
  const projectPath = useAppStore((state) => state.projectPath);
  const gitStatus = useAppStore((state) => state.gitStatus);
  const [refreshToken, setRefreshToken] = useState(0);
  const [externalChange, setExternalChange] = useState(false);

  const previousContent = useRef<string | null>(null);
  const active = activePath === docPath;

  // 首次挂载: 建卡 (解析对话 + 匹配角色)
  useEffect(() => {
    if (!doc) return;
    let disposed = false;
    void (async () => {
      const existing = voiceController.getCard(docPath);
      if (!existing) {
        await voiceController.openCard(docPath, docPath, doc.content, hash(doc.content));
      }
      if (!disposed) setRefreshToken((token) => token + 1);
    })();
    return () => {
      disposed = true;
    };
  }, [docPath]);

  // 文档内容变化 -> 重新解析
  useEffect(() => {
    if (!doc) return;
    if (previousContent.current === doc.content) return;
    const isFirstObservation = previousContent.current === null;
    previousContent.current = doc.content;
    if (isFirstObservation) return;
    void voiceController.refreshCard(docPath, doc.content).then(() => setRefreshToken((token) => token + 1));
  }, [doc?.content, docPath]);

  // 本地文件变更检测: 卡片激活时 + 定时轮询。
  // 检测到变更后**先请用户裁决**, 裁决完成才重新对齐历史 (顺序不可颠倒)。
  useEffect(() => {
    if (!active) return;
    let disposed = false;

    const check = async () => {
      if (disposed) return;
      const changed = await voiceController.checkDiskChange(docPath);
      if (!disposed && changed) setExternalChange(true);
    };

    void check();
    const timer = setInterval(() => void check(), DISK_CHECK_MS);
    const onFocus = () => void check();
    window.addEventListener('focus', onFocus);
    return () => {
      disposed = true;
      clearInterval(timer);
      window.removeEventListener('focus', onFocus);
    };
  }, [active, docPath]);

  // 光标位置变化 -> 定位当前对话
  const cursor = useAppStore((state) => state.cursor);
  useEffect(() => {
    if (!active || !cursor) return;
    const card = voiceController.getCard(docPath);
    if (!card) return;
    const line = cursor.line - 1;
    const dialogue = card.dialogues.find((item) => item.line === line);
    voiceController.setCursorLine(docPath, dialogue ? dialogue.line : null);
  }, [cursor?.line, active, docPath]);

  if (!doc) return null;
  if (!card) {
    return <div className="voice-card-loading">正在解析场景…</div>;
  }

  const dialogue: SayLine | null =
    card.cursorLine === null ? null : (card.dialogues.find((item) => item.line === card.cursorLine) ?? null);

  return (
    <div className="voice-card">
      <div className="voice-card-editor">
        <CodeEditor doc={doc} />
      </div>

      <div className="voice-card-panel">
        <div className="voice-panel-body">
          {dialogue ? (
            <div className="voice-panel-split">
              <VoiceSentencePanel
                cardId={docPath}
                dialogue={dialogue}
                characters={characters}
                refreshToken={refreshToken}
                onChanged={() => setRefreshToken((token) => token + 1)}
              />
              <VoiceHistory
                cardId={docPath}
                onChanged={() => setRefreshToken((token) => token + 1)}
                onApplied={() => setRefreshToken((token) => token + 1)}
              />
            </div>
          ) : (
            <div className="voice-panel-empty">
              <p>光标未落在对话语句上。</p>
              <p className="voice-panel-hint">将光标移动到任意一句对话（旁白或人物台词）上，即可在此配置并生成配音。</p>
              {card.history.length > 0 && (
                <Button
                  appearance="subtle"
                  icon={<ArrowSyncRegular />}
                  onClick={() => {
                    void voiceController.realignCard(docPath).then(() => setRefreshToken((token) => token + 1));
                  }}
                >
                  重新对齐 {card.history.length} 条历史记录
                </Button>
              )}
            </div>
          )}
        </div>
      </div>

      <ExternalChangeDialog
        open={externalChange}
        cardId={docPath}
        scenePath={docPath}
        inRepository={Boolean(projectPath && gitStatus)}
        onResolved={() => {
          setExternalChange(false);
          setRefreshToken((token) => token + 1);
        }}
        onOpenGitMerge={() => {
          // 用 git 合并: 打开该文件与 HEAD 的差异对比, 由用户在对比页里决定取舍
          const store = useAppStore.getState();
          store.openDiffTab({
            id: `diff-${docPath}`,
            title: `${doc?.name ?? '场景'}（合并）`,
            file: docPath,
            kind: 'unstaged',
          });
          setExternalChange(false);
        }}
      />
    </div>
  );
}

/** 与控制器一致的轻量内容哈希 */
function hash(text: string): string {
  let value = 0x811c9dc5;
  const normalized = text.replace(/\r\n/g, '\n');
  for (let index = 0; index < normalized.length; index++) {
    value ^= normalized.charCodeAt(index);
    value = Math.imul(value, 0x01000193);
  }
  return (value >>> 0).toString(16);
}

/** 空状态下的新增提示 (保留导出以便后续扩展) */
export const VOICE_CARD_EMPTY_ICON = AddRegular;
